<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class GradebookController extends Controller{
 public function index(Request $r,$group,$subject){$p=$r->attributes->get('academic_period');abort_if(!$p,404);$g=DB::table('study_groups')->find($group);$sub=DB::table('subjects')->find($subject);abort_if(!$g||!$sub,404);$u=$r->user();if(!$u->isSuperAdmin()&&!$u->hasRole('admin')&&!$u->hasRole('head_academic')){abort_unless($u->teacher_id&&DB::table('lesson_occurrences')->where('academic_period_id',$p->id)->where('study_group_id',$group)->where('subject_id',$subject)->where('teacher_id',$u->teacher_id)->exists(),403);}
  $lessons=DB::table('lesson_occurrences')->where('academic_period_id',$p->id)->where('study_group_id',$group)->where('subject_id',$subject)->where('status','!=','cancelled')->orderBy('lesson_date')->orderBy('lesson_number')->get();
  $mq=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$p->id)->where('m.study_group_id',$group)->where('m.status','active');$students=$mq->exists()?$mq->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$group)->where('status','active')->orderBy('last_name')->get();
  $ids=$lessons->pluck('id');$grades=DB::table('grade_records')->whereIn('lesson_occurrence_id',$ids)->get()->groupBy(fn($x)=>$x->student_id.'-'.$x->lesson_occurrence_id);$attendance=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$ids)->get()->keyBy(fn($x)=>$x->student_id.'-'.$x->lesson_occurrence_id);$results=DB::table('semester_results')->where('academic_period_id',$p->id)->where('subject_id',$subject)->whereIn('student_id',$students->pluck('id'))->pluck('value','student_id');foreach($students as $s){$sg=DB::table('grade_records as gr')->whereIn('gr.lesson_occurrence_id',$ids)->where('gr.student_id',$s->id)->whereIn('gr.value',['2','3','4','5']);$s->avg=$sg->avg(DB::raw('CAST(gr.value AS REAL)'));$marked=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$ids)->where('student_id',$s->id)->count();$present=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$ids)->where('student_id',$s->id)->whereIn('status',['present','late'])->count();$s->attendance_pct=$marked?round($present*100/$marked):null;}
  return view('gradebook.index',compact('p','g','sub','lessons','students','grades','attendance','results'));
 }
}